/**
 * Rich-text document model: plain text plus a set of non-overlapping,
 * normalized mark ranges.
 *
 * Invariants maintained after every operation:
 *  - Mark ranges are sorted by `from` and never overlap.
 *  - Identical adjacent ranges (same type + attrs, touching bounds) are merged.
 *  - Empty ranges (from === to) never exist.
 *
 * Every mutating operation returns the applied Op, which carries enough
 * information for `invert()` to produce its exact inverse (used by History).
 */

export type Attrs = Record<string, unknown>;

export interface MarkRange {
  from: number;
  to: number;
  type: string;
  attrs?: Attrs;
}

export interface Doc {
  text: string;
  marks: MarkRange[];
}

export function emptyDoc(): Doc {
  return { text: '', marks: [] };
}

/* ------------------------------------------------------------------ */
/* Mark-type registry                                                  */
/* ------------------------------------------------------------------ */

/**
 * Per-type configuration. `inclusive` controls whether an insertion made
 * exactly at one of the mark's boundaries extends the mark (true) or is
 * left outside of it (false).
 */
export interface MarkTypeInfo {
  /** true -> insertions at either boundary join the mark; false -> they don't. */
  inclusive: boolean;
}

export const MARK_TYPES: Record<string, MarkTypeInfo> = {
  bold: { inclusive: true },
  italic: { inclusive: true },
  link: { inclusive: false },
};

export function isInclusive(type: string): boolean {
  const info = MARK_TYPES[type];
  if (!info) throw new Error(`Unknown mark type: ${type}`);
  return info.inclusive;
}

/* ------------------------------------------------------------------ */
/* Operations                                                          */
/* ------------------------------------------------------------------ */

export type Op =
  | { kind: 'insert'; pos: number; text: string }
  /**
   * Delete of text in [from, to). `text` is the removed string, `prevMarks`
   * is a deep copy of doc.marks before deletion — needed because deletion
   * can trim, collapse or merge ranges in ways only fully reversible by
   * restoring the prior set.
   */
  | { kind: 'delete'; from: number; to: number; text: string; prevMarks: MarkRange[] }
  | { kind: 'addMark'; from: number; to: number; markType: string; attrs: Attrs; prevMarks: MarkRange[] }
  | { kind: 'removeMark'; from: number; to: number; markType: string; prevMarks: MarkRange[] }
  /**
   * Restore an exact mark set. Only produced by invert() — never by the
   * public editing operations.
   */
  | { kind: 'setMarks'; marks: MarkRange[] };

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

const clone = <T>(v: T): T => structuredClone(v);

function checkPos(doc: Doc, pos: number, what = 'pos'): void {
  if (!Number.isInteger(pos) || pos < 0 || pos > doc.text.length) {
    throw new RangeError(`Invalid ${what} ${pos} for text of length ${doc.text.length}`);
  }
}

function checkRange(doc: Doc, from: number, to: number): void {
  if (!Number.isInteger(from) || !Number.isInteger(to)) {
    throw new RangeError(`Range bounds must be integers, got ${from}..${to}`);
  }
  if (from > to) throw new RangeError(`Invalid range ${from}..${to}: from > to`);
  checkPos(doc, from, 'from');
  checkPos(doc, to, 'to');
}

/** Stable equality for attr objects (key-order independent). */
export function attrsEqual(a?: Attrs, b?: Attrs): boolean {
  return JSON.stringify(sortAttrs(a ?? {})) === JSON.stringify(sortAttrs(b ?? {}));
}

function sortAttrs(attrs: Attrs): Attrs {
  const out: Attrs = {};
  for (const k of Object.keys(attrs).sort()) out[k] = attrs[k];
  return out;
}

function sameIdentity(a: MarkRange, b: MarkRange): boolean {
  return a.type === b.type && attrsEqual(a.attrs, b.attrs);
}

/**
 * Enforce normalization invariants: drop empties, sort, and merge identical
 * adjacent/overlapping ranges.
 */
export function normalizeMarks(marks: MarkRange[]): MarkRange[] {
  const sorted = marks
    .filter((m) => m.to > m.from)
    .sort((a, b) => a.from - b.from || a.to - b.to || a.type.localeCompare(b.type));
  const out: MarkRange[] = [];
  for (const m of sorted) {
    const last = out[out.length - 1];
    if (last && sameIdentity(last, m) && m.from <= last.to) {
      last.to = Math.max(last.to, m.to);
    } else {
      out.push(clone(m));
    }
  }
  return out;
}

/* ------------------------------------------------------------------ */
/* Editing operations (mutate doc, return the applied Op)              */
/* ------------------------------------------------------------------ */

/**
 * Insert `str` at `pos`.
 *
 * Mark adjustment per boundary b:
 *   b <  pos        -> unchanged
 *   b == pos        -> shift by len iff inclusive (boundary extends the mark),
 *                      otherwise unchanged... except the *far* side logic below
 *   b >  pos        -> shift by len
 *
 * Net effect: inserting strictly inside grows the range; at a boundary it
 * extends the mark only when the type is inclusive.
 */
export function insertText(doc: Doc, pos: number, str: string): Extract<Op, { kind: 'insert' }> {
  checkPos(doc, pos);
  if (typeof str !== 'string') throw new TypeError('insertText expects a string');
  if (str.length === 0) return { kind: 'insert', pos, text: '' };

  const len = str.length;
  doc.text = doc.text.slice(0, pos) + str + doc.text.slice(pos);

  const inclusiveCache = new Map<string, boolean>();
  for (const m of doc.marks) {
    let incl = inclusiveCache.get(m.type);
    if (incl === undefined) {
      incl = isInclusive(m.type);
      inclusiveCache.set(m.type, incl);
    }
    // Start boundary.
    if (pos < m.from || (pos === m.from && !incl)) m.from += len;
    // End boundary.
    if (pos < m.to || (pos === m.to && incl)) m.to += len;
  }
  return { kind: 'insert', pos, text: str };
}

/**
 * Delete text in [from, to).
 *
 * Marks overlapping the deleted span are trimmed/collapsed via boundary
 * mapping:
 *   b <= from -> unchanged
 *   b >= to   -> b - (to - from)
 *   otherwise -> clamped to `from`
 * Ranges that end up empty are removed. Afterwards identical adjacent
 * ranges are merged (deletion can close the gap between two equal runs).
 */
export function deleteRange(
  doc: Doc,
  from: number,
  to: number
): Extract<Op, { kind: 'delete' }> {
  checkRange(doc, from, to);
  const removed = doc.text.slice(from, to);
  if (removed.length === 0) {
    return { kind: 'delete', from, to, text: '', prevMarks: clone(doc.marks) };
  }

  const prevMarks = clone(doc.marks);
  doc.text = doc.text.slice(0, from) + doc.text.slice(to);

  const width = to - from;
  const mapBound = (b: number): number =>
    b <= from ? b : b >= to ? b - width : from;

  const next: MarkRange[] = [];
  for (const m of doc.marks) {
    const nf = mapBound(m.from);
    const nt = mapBound(m.to);
    if (nt > nf) next.push({ ...clone(m), from: nf, to: nt });
  }
  doc.marks = normalizeMarks(next);
  return { kind: 'delete', from, to, text: removed, prevMarks };
}

/**
 * Apply mark `type` with `attrs` over [from, to).
 *
 * Same-type marks overlapping the range are absorbed when their attrs match
 * (the applied range grows to cover them), or split around the range when
 * their attrs differ. Normalization then merges any identical adjacent
 * ranges created along the way.
 */
export function addMark(
  doc: Doc,
  from: number,
  to: number,
  type: string,
  attrs: Attrs = {}
): Extract<Op, { kind: 'addMark' }> {
  checkRange(doc, from, to);
  isInclusive(type); // validates the type name
  const prevMarks = clone(doc.marks);

  let lo = from;
  let hi = to;
  const kept: MarkRange[] = [];
  for (const m of doc.marks) {
    if (m.type !== type || m.to <= from || m.from >= to) {
      kept.push(m);
      continue;
    }
    if (attrsEqual(m.attrs, attrs)) {
      lo = Math.min(lo, m.from);
      hi = Math.max(hi, m.to);
    } else {
      // Split: keep the parts outside [from, to).
      if (m.from < from) kept.push({ ...clone(m), to: from });
      if (m.to > to) kept.push({ ...clone(m), from: to });
    }
  }
  kept.push({ from: lo, to: hi, type, attrs: { ...attrs } });
  doc.marks = normalizeMarks(kept);
  return { kind: 'addMark', from, to, markType: type, attrs: { ...attrs }, prevMarks };
}

/**
 * Remove mark `type` wherever it overlaps [from, to). Overlapping ranges are
 * trimmed; a range straddling the span is split into the two surviving parts.
 */
export function removeMark(
  doc: Doc,
  from: number,
  to: number,
  type: string
): Extract<Op, { kind: 'removeMark' }> {
  checkRange(doc, from, to);
  isInclusive(type); // validates the type name
  const prevMarks = clone(doc.marks);

  const kept: MarkRange[] = [];
  for (const m of doc.marks) {
    if (m.type !== type || m.to <= from || m.from >= to) {
      kept.push(m);
      continue;
    }
    if (m.from < from) kept.push({ ...clone(m), to: from });
    if (m.to > to) kept.push({ ...clone(m), from: to });
  }
  doc.marks = normalizeMarks(kept);
  return { kind: 'removeMark', from, to, markType: type, prevMarks };
}

/* ------------------------------------------------------------------ */
/* Applying & inverting operations                                     */
/* ------------------------------------------------------------------ */

/** Apply any op (forward direction) to a document. */
export function applyOp(doc: Doc, op: Op): void {
  switch (op.kind) {
    case 'insert': {
      checkPos(doc, op.pos);
      doc.text = doc.text.slice(0, op.pos) + op.text + doc.text.slice(op.pos);
      const len = op.text.length;
      const cache = new Map<string, boolean>();
      for (const m of doc.marks) {
        let incl = cache.get(m.type);
        if (incl === undefined) {
          incl = isInclusive(m.type);
          cache.set(m.type, incl);
        }
        if (op.pos < m.from || (op.pos === m.from && !incl)) m.from += len;
        if (op.pos < m.to || (op.pos === m.to && incl)) m.to += len;
      }
      break;
    }
    case 'delete': {
      checkRange(doc, op.from, op.to);
      if (doc.text.slice(op.from, op.to) !== op.text) {
        throw new Error('delete op does not match document text');
      }
      doc.text = doc.text.slice(0, op.from) + doc.text.slice(op.to);
      const width = op.to - op.from;
      const mapBound = (b: number): number =>
        b <= op.from ? b : b >= op.to ? b - width : op.from;
      const next: MarkRange[] = [];
