 * `marksNow` must be doc.marks in the state right after `op` was applied
 * (History passes the live document's marks). The returned op, applied to
 * that state, restores the document exactly as it was before `op`.
 */
export function invert(op: Op, marksNow: MarkRange[]): Op {
  switch (op.kind) {
    case 'insert':
      // Undoing an insert is deleting the inserted text. Deletion's forward
      // mark math restores the exact prior boundaries (insertion never drops
      // or merges marks).
      return {
        kind: 'delete',
        from: op.pos,
        to: op.pos + op.text.length,
        text: op.text,
        prevMarks: clone(marksNow),
      };
    case 'delete':
      // Re-insert the removed text and restore the pre-delete mark set
      // wholesale (deletion may have merged adjacent identical ranges).
      return { kind: 'insert', pos: op.from, text: op.text, restoreMarks: clone(op.prevMarks) };
    case 'addMark':
    case 'removeMark':
      return { kind: 'setMarks', marks: clone(op.prevMarks) };
    case 'setMarks':
      throw new Error('cannot invert a setMarks op without knowing the post-state');
  }
}
