/**
 * Undo/redo history for a Doc. Stacks applied operations; undo applies
 * invert(op) to the live document, redo replays the original op.
 */
import type { Doc, Op, MarkRange } from './doc.js';
import { applyOp, invert } from './doc.js';

export class History {
  private undoStack: Op[] = [];
  private redoStack: Op[] = [];

  constructor(private readonly doc: Doc) {}

  /** Record an op that has already been applied to the document. */
  record(op: Op): void {
    this.undoStack.push(op);
    this.redoStack = [];
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  get depth(): number {
    return this.undoStack.length;
  }

  /**
   * Undo the most recent operation. Returns true if something was undone.
   * The inverse op is derived from the current (post-op) mark state, so it
   * restores text and marks exactly.
   */
  undo(): boolean {
    const op = this.undoStack.pop();
    if (!op) return false;
    const inverse = invert(op, this.doc.marks as MarkRange[]);
    applyOp(this.doc, inverse);
    this.redoStack.push(op);
    return true;
  }

  /** Redo the most recently undone operation. Returns true if applied. */
  redo(): boolean {
    const op = this.redoStack.pop();
    if (!op) return false;
    applyOp(this.doc, op);
    this.undoStack.push(op);
    return true;
  }

  /** Drop all history (e.g. after replacing the document wholesale). */
  clear(): void {
    this.undoStack = [];
    this.redoStack = [];
  }
}

