import { describe, it, expect } from 'vitest';
import {
  emptyDoc,
  insertText,
  deleteRange,
  addMark,
  removeMark,
  applyOp,
  invert,
  normalizeMarks,
  isInclusive,
  type Doc,
  type MarkRange,
  type Op,
} from '../src/doc.js';

function doc(text: string, marks: MarkRange[] = []): Doc {
  return { text, marks };
}

/** Type-level helper: only the mark(s) of `type`, as [from,to] tuples. */
function boundsOf(d: Doc, type: string): Array<[number, number]> {
  return d.marks.filter((m) => m.type === type).map((m) => [m.from, m.to] as [number, number]);
}

describe('mark-type inclusivity registry', () => {
  it('bold/italic are inclusive, link is not', () => {
    expect(isInclusive('bold')).toBe(true);
    expect(isInclusive('italic')).toBe(true);
    expect(isInclusive('link')).toBe(false);
  });

  it('rejects unknown types', () => {
    expect(() => isInclusive('strike')).toThrow();
    expect(() => addMark(doc('ab'), 0, 1, 'strike')).toThrow();
  });
});

describe('insertText mark math — inclusive marks (bold)', () => {
  // "abcdef" with bold over "bcd" = [1,4)
  const base = () => doc('abcdef', [{ from: 1, to: 4, type: 'bold' }]);

  it('insert at start boundary extends the mark', () => {
    const d = base();
    insertText(d, 1, 'X');
    expect(d.text).toBe('aXbcdef');
    expect(boundsOf(d, 'bold')).toEqual([[1, 5]]);
  });

  it('insert strictly inside grows the mark', () => {
    const d = base();
    insertText(d, 3, 'XY');
    expect(d.text).toBe('abcXYdef');
    expect(boundsOf(d, 'bold')).toEqual([[1, 6]]);
  });

  it('insert at end boundary extends the mark', () => {
    const d = base();
    insertText(d, 4, 'Z');
    expect(d.text).toBe('abcdZef');
    expect(boundsOf(d, 'bold')).toEqual([[1, 5]]);
  });

  it('insert before the mark shifts both bounds', () => {
    const d = base();
    insertText(d, 0, 'QQ');
    expect(boundsOf(d, 'bold')).toEqual([[3, 6]]);
  });

  it('insert after the mark leaves it untouched', () => {
    const d = base();
    insertText(d, 6, '!');
    expect(boundsOf(d, 'bold')).toEqual([[1, 4]]);
  });
});

describe('insertText mark math — non-inclusive marks (link)', () => {
  const base = () =>
    doc('abcdef', [{ from: 1, to: 4, type: 'link', attrs: { href: 'https://x' } }]);

  it('insert at start boundary stays outside the mark', () => {
    const d = base();
    insertText(d, 1, 'X');
    expect(d.text).toBe('aXbcdef');
    expect(boundsOf(d, 'link')).toEqual([[2, 5]]);
  });

  it('insert strictly inside grows the mark', () => {
    const d = base();
    insertText(d, 2, 'Y');
    expect(d.text).toBe('abYcdef');
    expect(boundsOf(d, 'link')).toEqual([[1, 5]]);
  });

  it('insert at end boundary stays outside the mark', () => {
    const d = base();
    insertText(d, 4, 'Z');
    expect(d.text).toBe('abcdZef');
    expect(boundsOf(d, 'link')).toEqual([[1, 4]]);
  });

  it('insert before shifts both bounds', () => {
    const d = base();
    insertText(d, 0, 'W');
    expect(boundsOf(d, 'link')).toEqual([[2, 5]]);
  });
});

describe('deleteRange mark math', () => {
  it('trims a mark when the deletion straddles its end boundary', () => {
    const d = doc('abcdefgh', [{ from: 2, to: 6, type: 'bold' }]);
    deleteRange(d, 4, 8);
    expect(d.text).toBe('abcd');
    expect(boundsOf(d, 'bold')).toEqual([[2, 4]]);
  });

  it('trims a mark when the deletion straddles its start boundary', () => {
    const d = doc('abcdefgh', [{ from: 2, to: 6, type: 'bold' }]);
    deleteRange(d, 0, 4);
    expect(d.text).toBe('efgh');
    expect(boundsOf(d, 'bold')).toEqual([[0, 2]]);
  });

  it('removes a mark fully contained in the deleted span', () => {
    const d = doc('abcdefgh', [
      { from: 3, to: 5, type: 'bold' },
      { from: 0, to: 1, type: 'italic' },
    ]);
    deleteRange(d, 2, 6);
    expect(d.text).toBe('abgh');
    expect(boundsOf(d, 'bold')).toEqual([]);
    expect(boundsOf(d, 'italic')).toEqual([[0, 1]]);
  });

  it('removes a mark deleted exactly edge-to-edge', () => {
    const d = doc('abcdef', [{ from: 2, to: 5, type: 'bold' }]);
    deleteRange(d, 2, 5);
    expect(boundsOf(d, 'bold')).toEqual([]);
  });

  it('shifts a mark lying wholly after the deleted span', () => {
    const d = doc('abcdefgh', [{ from: 5, to: 7, type: 'italic' }]);
    deleteRange(d, 1, 3);
    expect(boundsOf(d, 'italic')).toEqual([[3, 5]]);
  });

  it('leaves a mark lying wholly before the deleted span alone', () => {
    const d = doc('abcdefgh', [{ from: 0, to: 2, type: 'italic' }]);
    deleteRange(d, 5, 8);
    expect(boundsOf(d, 'italic')).toEqual([[0, 2]]);
  });

  it('deleting zero-width is a no-op', () => {
    const d = doc('abc', [{ from: 0, to: 3, type: 'bold' }]);
    const op = deleteRange(d, 1, 1);
    expect(op.text).toBe('');
    expect(d.text).toBe('abc');
    expect(boundsOf(d, 'bold')).toEqual([[0, 3]]);
  });

  it('rejects invalid ranges', () => {
    const d = doc('abc');
    expect(() => deleteRange(d, 2, 1)).toThrow(RangeError);
    expect(() => deleteRange(d, -1, 2)).toThrow(RangeError);
    expect(() => deleteRange(d, 0, 4)).toThrow(RangeError);
  });
});

describe('merging identical adjacent ranges', () => {
  it('deletion that closes the gap merges two equal runs', () => {
    const d = doc('abcdefgh', [
      { from: 0, to: 2, type: 'bold' },
      { from: 4, to: 6, type: 'bold' },
    ]);
    deleteRange(d, 2, 4);
    expect(d.text).toBe('abefgh');
    expect(boundsOf(d, 'bold')).toEqual([[0, 4]]);
  });

  it('addMark flush with an equal run merges into one range', () => {
    const d = doc('abcd', [{ from: 0, to: 2, type: 'bold' }]);
    addMark(d, 2, 4, 'bold');
    expect(d.marks).toHaveLength(1);
    expect(boundsOf(d, 'bold')).toEqual([[0, 4]]);
  });

  it('overlapping equal runs collapse via addMark', () => {
    const d = doc('abcdef', [{ from: 0, to: 4, type: 'bold' }]);
    addMark(d, 2, 6, 'bold');
    expect(d.marks).toHaveLength(1);
    expect(boundsOf(d, 'bold')).toEqual([[0, 6]]);
  });

  it('adjacent runs with different attrs do NOT merge', () => {
    const d = doc('abcd');
    addMark(d, 0, 2, 'link', { href: 'a' });
    addMark(d, 2, 4, 'link', { href: 'b' });
    expect(d.marks).toHaveLength(2);
  });

  it('adjacent runs of different types do NOT merge', () => {
    const d = doc('abcd');
    addMark(d, 0, 2, 'bold');
    addMark(d, 2, 4, 'italic');
    expect(d.marks).toHaveLength(2);
  });
});

describe('addMark absorption & splitting', () => {
  it('absorbs an overlapping same-type mark with equal attrs', () => {
    const d = doc('abcdef', [{ from: 0, to: 4, type: 'bold' }]);
    addMark(d, 3, 6, 'bold');
    expect(d.marks).toHaveLength(1);
    expect(boundsOf(d, 'bold')).toEqual([[0, 6]]);
  });

  it('splits an overlapping same-type mark with different attrs into three parts', () => {
    const d = doc('abcdef', [{ from: 0, to: 6, type: 'link', attrs: { href: 'x' } }]);
    addMark(d, 2, 4, 'link', { href: 'y' });
    const links = d.marks.filter((m) => m.type === 'link');
    expect(links).toEqual([
      { from: 0, to: 2, type: 'link', attrs: { href: 'x' } },
      { from: 2, to: 4, type: 'link', attrs: { href: 'y' } },
      { from: 4, to: 6, type: 'link', attrs: { href: 'x' } },
    ]);
  });

  it('other mark types are untouched by addMark', () => {
    const d = doc('abcdef', [{ from: 0, to: 6, type: 'italic' }]);
    addMark(d, 1, 5, 'bold');
    expect(boundsOf(d, 'italic')).toEqual([[0, 6]]);
    expect(boundsOf(d, 'bold')).toEqual([[1, 5]]);
  });
});

describe('removeMark trimming & splitting', () => {
  it('trims the tail of a mark', () => {
    const d = doc('abcdef', [{ from: 0, to: 4, type: 'bold' }]);
    removeMark(d, 2, 6, 'bold');
    expect(boundsOf(d, 'bold')).toEqual([[0, 2]]);
  });

  it('trims the head of a mark', () => {
    const d = doc('abcdef', [{ from: 2, to: 6, type: 'bold' }]);
    removeMark(d, 0, 4, 'bold');
    expect(boundsOf(d, 'bold')).toEqual([[4, 6]]);
  });

  it('splits a mark straddled by the removal span', () => {
    const d = doc('abcdef', [{ from: 0, to: 6, type: 'bold' }]);
    removeMark(d, 2, 4, 'bold');
    expect(boundsOf(d, 'bold')).toEqual([
      [0, 2],
      [4, 6],
    ]);
  });

  it('only affects the requested type', () => {
    const d = doc('abcdef', [
      { from: 0, to: 6, type: 'bold' },
      { from: 0, to: 6, type: 'link', attrs: { href: 'h' } },
    ]);
    removeMark(d, 1, 5, 'bold');
    expect(boundsOf(d, 'bold')).toEqual([
      [0, 1],
      [5, 6],
    ]);
    expect(boundsOf(d, 'link')).toEqual([[0, 6]]);
  });
});

describe('operation inverses restore documents exactly', () => {
  function roundTrip(build: (d: Doc) => Op[], expectText: string) {
    const d = doc('one two three', [
      { from: 0, to: 3, type: 'bold' },
      { from: 4, to: 7, type: 'link', attrs: { href: '/u' } },
      { from: 8, to: 13, type: 'italic' },
    ]);
    const before = structuredClone(d);
    const ops = build(d);
    expect(d.text).toBe(expectText);
    for (const op of ops.reverse()) {
      applyOp(d, invert(op, d.marks));
    }
    expect(d).toEqual(before);
  }

  it('inverts insert', () => {
    roundTrip((d) => [insertText(d, 5, 'BIG ')], 'one BIG two three');
  });

  it('inverts delete (including mark merging done by the delete)', () => {
    // Deleting the space between two italic runs merges them; the inverse
    // must restore the original two separate ranges.
    const seed = doc('aaaa bb aa', [
      { from: 0, to: 4, type: 'italic' },
      { from: 7, to: 9, type: 'italic' },
    ]);
    const before = structuredClone(seed);
    const op = deleteRange(seed, 4, 7); // -> italics become adjacent identical
    expect(boundsOf(seed, 'italic')).toEqual([[0, 6]]);
    applyOp(seed, invert(op, seed.marks));
    expect(seed).toEqual(before);
  });

  it('inverts addMark', () => {
    roundTrip((d) => [addMark(d, 2, 11, 'link', { href: '/n' })], 'one two three');
  });

  it('inverts removeMark', () => {
    roundTrip((d) => [removeMark(d, 1, 10, 'italic')], 'one two three');
  });

  it('inverts a mixed sequence', () => {
    roundTrip(
      (d) => [
        insertText(d, 13, '!?'),
        addMark(d, 0, 4, 'bold'),
        deleteRange(d, 4, 8),
        insertText(d, 2, 'X'),
        removeMark(d, 0, 3, 'link'),
        addMark(d, 1, 9, 'italic', { level: 2 }),
        deleteRange(d, 5, 7),
      ],
      'onXtwothree!?'
    );
  });
});

describe('normalization invariants', () => {
  it('normalizeMarks drops empties, sorts and merges', () => {
    const out = normalizeMarks([
      { from: 5, to: 7, type: 'bold' },
      { from: 3, to: 3, type: 'italic' },
      { from: 0, to: 5, type: 'bold' },
      { from: 1, to: 2, type: 'italic' },
    ]);
    expect(out).toEqual([
      { from: 0, to: 7, type: 'bold' },
      { from: 1, to: 2, type: 'italic' },
    ]);
  });
});

