export function normalizeMarks(marks: MarkRange[]): MarkRange[] {
  const sorted = marks
    .filter((m) => m.to > m.from)
    .sort((a, b) => a.from - b.from || a.to - b.to || a.type.localeCompare(b.type));
  const out: MarkRange[] = [];
  for (const m of sorted) {
    // Find any already-accepted range of the same identity that this one
    // touches or overlaps (a different-type range may sort in between, so
    // checking only the last element is not enough).
    const target = out.find((r) => sameIdentity(r, m) && m.from <= r.to);
    if (target) {
      target.to = Math.max(target.to, m.to);
    } else {
      out.push(clone(m));
    }
  }
  // Extension via merges can disturb sort order; restore it.
  return out.sort((a, b) => a.from - b.from || a.to - b.to || a.type.localeCompare(b.type));
}

