import { it } from 'vitest';
import { writeFileSync } from 'node:fs';
import { insertText, deleteRange, addMark, type Doc } from '../src/doc.js';
import { History } from '../src/history.js';

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const log: string[] = [];
it('debug', () => {
  try {
    const rand = mulberry32(999);
    const d: Doc = { text: '', marks: [] };
    const h = new History(d);
    const snapshots: Doc[] = [];
    for (let i = 0; i < 60; i++) {
      const roll = rand();
      if (roll < 0.1 && h.canUndo) { h.undo(); }
      else if (roll < 0.2 && h.canRedo) { h.redo(); }
      else {
        const len = d.text.length;
        if (rand() < 0.6 || len === 0) {
          const pos = Math.floor(rand() * (len + 1));
          h.record(insertText(d, pos, 'abc'[Math.floor(rand() * 3)]!));
        } else {
          const from = Math.floor(rand() * len);
          const to = from + 1 + Math.floor(rand() * (len - from));
          if (rand() < 0.5) h.record(deleteRange(d, from, to));
          else h.record(addMark(d, from, to, rand() < 0.5 ? 'bold' : 'link', { href: '/x' }));
        }
      }
      snapshots.push(structuredClone(d));
      // verify undo-k consistency incrementally
      let k = 0;
      const saved = structuredClone(d);
      while (h.undo()) { k++; if (JSON.stringify(d) !== JSON.stringify(snapshots[snapshots.length - 1 - k])) { log.push(`step ${i}: mismatch at k=${k}\n got=${JSON.stringify(d)}\n want=${JSON.stringify(snapshots[snapshots.length-1-k])}`); break; } }
      while (h.redo());
      if (JSON.stringify(d) !== JSON.stringify(saved)) log.push(`step ${i}: redo mismatch`);
    }
  } finally {
    writeFileSync('/tmp/trace.txt', log.join('\n') || 'ALL OK');
  }
});
