it('interleaved undo/redo/edit stays consistent', () => {
  const rand = mulberry32(999);
  const d = emptyDoc();
  const h = new History(d);
  let recorded = 0;

  for (let i = 0; i < 60; i++) {
    const roll = rand();
    if (roll < 0.1 && h.canUndo) {
      h.undo();
    } else if (roll < 0.2 && h.canRedo) {
      h.redo();
    } else {
      const len = d.text.length;
      if (rand() < 0.6 || len === 0) {
        const pos = Math.floor(rand() * (len + 1));
        h.record(insertText(d, pos, 'abc'[Math.floor(rand() * 3)]!));
      } else {
        const from = Math.floor(rand() * len);
        const to = from + 1 + Math.floor(rand() * (len - from));
        if (rand() < 0.5) h.record(deleteRange(d, from, to));
        else h.record(addMark(d, from, to, rand() < 0.5 ? 'bold' : 'link', { href: '/x' }));
      }
      recorded++;
    }
    assertInvariants(d);
  }

  expect(h.depth).toBe(recorded);
  const finalState = structuredClone(d);

  // Undoing every recorded op must restore the pristine document.
  while (h.undo());
  expect(h.depth).toBe(0);
  expect(d).toEqual(emptyDoc());
  assertInvariants(d);

  // And redoing them all must restore the final state.
  let redos = 0;
  while (h.redo()) redos++;
  expect(redos).toBe(recorded);
  expect(d).toEqual(finalState);
  assertInvariants(d);
});

